css:
.mz *,.mz *::before,.mz *::after{box-sizing: border-box; margin: 0; padding: 0;}
.mz .tabla-lineas{width: 100%; border-collapse: collapse;}
.mz .tabla-lineas th{border: 1.5px solid var(--bosque); background: #eee; font-size: 12px; padding: 4px 6px;}
.mz .tabla-lineas td{border: 1.5px solid var(--bosque); text-align: center; padding: 3px 6px;}
.mz .celda-linea{width: 34%;}
.mz .celda-marca{width: 22%; height: 48px;}
.mz .linea-svg{width: 96px; height: 42px; display: block; margin: 0 auto;}
.mz .contar-grid{display: grid; grid-template-columns: repeat(4, 1fr); gap: 10px;}
.mz .contar-caja{border: 1.5px solid var(--bosque); border-radius: 8px; padding: 5px 4px 6px; display: flex; flex-direction: column; align-items: center; gap: 4px;}
.mz .contar-svg{width: 100%; height: 64px;}
.mz .hueco-num{display: inline-block; border: 1.5px solid var(--bosque); border-radius: 5px; width: 38px; height: 26px;}
.mz .mosaico-grid{display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px;}
.mz .mosaico-caja{border: 1.5px dashed #000; border-radius: 8px; padding: 6px 4px; display: flex; align-items: center; justify-content: center;}
.mz .mosaico-svg{width: 100%; height: 62px;}
.mz .dibujar-grid{display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px;}
.mz .dibujar-caja{display: flex; flex-direction: column; align-items: center; gap: 4px;}
.mz .dibujar-titulo{font-size: 12.5px; font-weight: 700; text-align: center; line-height: 1.25;}
.mz .dibujar-zona{border: 1.5px solid var(--bosque); border-radius: 8px; width: 100%; height: 110px;}
.mz .dibujar-titulo{line-height: 1.725 !important;}
